/*
 * NOVA ATELIER — Footer Colophon
 * 1) COMPOSITION: A 6.8x2.0 machined-metal footer band floats in front of a 7x6 graded
 *    backdrop (z=-2.5). Left 2.0u = wordmark + accent underline; three 1.2u link columns
 *    (0.375u gutters) fill the right; a legal line + second hairline sit near the bottom.
 * 2) LIGHT RIG: rig-gallery-soft — ambient floor 0.3, key directional #fff8f0 @1.9 upper-left,
 *    hemisphere fill #f2eee8 @0.65, rim directional #ffffff @0.8 from behind-low, so the
 *    hairline rules pick up a faint graze/specular edge (etched, not drawn).
 * 3) MATERIALS: band + backdrop use MeshStandardNodeMaterial with a TSL vertical-gradient
 *    colorNode (#121218 -> #0b0b10), roughness 0.6 / metalness 0.2 (brushed, non-blown);
 *    hairlines are thin low-roughness metal strips (#23232b); accent bar is emissive #ff2a38.
 * 4) MOTION: ONE mount timeline — the whole band fades opacity 0->1 and rises y+0.2->0 over
 *    500ms power2.out (no per-item stagger); idle state holds still (no perpetual motion).
 * 5) FOCAL ELEMENT: the emissive #ff2a38 accent bar beneath the wordmark — the single
 *    brightest read in an otherwise dark, etched-metal band.
 */

import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DirectionalLight, HemisphereLight, AmbientLight, Vector3 } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#101015',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#121218' }, { at: 1, hex: '#0b0b10' }],
  };
  const PAPER = colors.paper;
  const ACCENT = colors.accent;
  const HAIRLINE_HEX = '#23232b';
  const RAMP_TOP = colors.gradientStops?.[0]?.hex ?? '#121218';
  const RAMP_BOTTOM = colors.gradientStops?.[1]?.hex ?? '#0b0b10';

  const disposables = { geometries: [], materials: [], lights: [] };

  // ---- root ----
  const root = new Group();
  root.name = 'footer-colophon';

  // ---- shared vertical-gradient TSL node (RAMP_TOP at uv.y=1, RAMP_BOTTOM at uv.y=0) ----
  function gradientNode() {
    return mix(color(RAMP_BOTTOM), color(RAMP_TOP), uv().y);
  }

  // ---- section: stage backdrop (never-void law) ----
  function buildBackdrop() {
    const geo = new PlaneGeometry(7, 6);
    const mat = new MeshStandardNodeMaterial({ roughness: 0.85, metalness: 0.05 });
    mat.colorNode = gradientNode();
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, 0, -2.5);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    root.add(mesh);
    return mesh;
  }

  // ---- section: the footer band itself ----
  function buildBand() {
    const geo = new PlaneGeometry(6.8, 2.0);
    const mat = new MeshStandardNodeMaterial({ roughness: 0.6, metalness: 0.2 });
    mat.colorNode = gradientNode();
    mat.transparent = true;
    mat.opacity = 1;
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, 0, 0);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    band.add(mesh);
    return mesh;
  }

  function makeHairline(y, widthOverride) {
    const w = widthOverride ?? 6.8;
    const geo = new PlaneGeometry(w, 0.006);
    const mat = new MeshStandardNodeMaterial({
      roughness: 0.35,
      metalness: 0.4,
      color: HAIRLINE_HEX,
      transparent: true,
    });
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, y, 0.015);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    band.add(mesh);
    return mesh;
  }

  function makeAccentBar(x, y) {
    const geo = new PlaneGeometry(0.3, 0.02);
    const mat = new MeshStandardNodeMaterial({
      roughness: 0.5,
      metalness: 0.1,
      color: ACCENT,
      transparent: true,
    });
    mat.emissiveNode = color(ACCENT).mul(1.4);
    const mesh = new Mesh(geo, mat);
    mesh.position.set(x, y, 0.02);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    band.add(mesh);
    return mesh;
  }

  // ---- section: lighting rig (rig-gallery-soft) ----
  function buildLights() {
    const r = 1.7; // band-relative bounding radius scale
    const ambient = new AmbientLight(0xffffff, 0.3);
    root.add(ambient);
    disposables.lights.push(ambient);

    const key = new DirectionalLight(0xfff8f0, 1.9);
    key.position.set(0.8 * r, 3.4 * r, 2 * r);
    key.target.position.set(0, 0.5, 0);
    root.add(key, key.target);
    disposables.lights.push(key);

    const fill = new HemisphereLight(0xf2eee8, 0x0b0b10, 0.65);
    root.add(fill);
    disposables.lights.push(fill);

    const rim = new DirectionalLight(0xffffff, 0.8);
    rim.position.set(0.4 * r, 1.8 * r, -2.8 * r);
    rim.target.position.set(0, 0.6, 0);
    root.add(rim, rim.target);
    disposables.lights.push(rim);
  }

  // ---- text helpers ----
  const textMeshes = [];
  function makeText(str, { fontSize, color: col, letterSpacingEm = 0, align = 'left' }, x, y) {
    const letterSpacingPx = letterSpacingEm * fontSize;
    const obj = ctx.fontAtlas.createText(str, {
      fontSize,
      color: col,
      align,
      letterSpacingPx,
    });
    obj.position.set(x, y, 0.02);
    band.add(obj);
    textMeshes.push(obj);
    return obj;
  }

  // ---- section: bridge textContent items into layout slots ----
  function buildText() {
    const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
    const typo = config?.intent?.visualSpec?.typography ?? {
      wordmark: { fontSize: 34, letterSpacing: 0.02 },
      'column-header': { fontSize: 9, letterSpacing: 0.12 },
      link: { fontSize: 13, letterSpacing: 0 },
      legal: { fontSize: 9, letterSpacing: 0.04 },
    };

    // Layout constants (band-local space, band spans x[-3.4,3.4] y[-1,1])
    const leftPad = -3.4 + 0.25;
    const colStartX = [-1.025 + 0.05, 0.55 + 0.05, 2.125 + 0.05];
    const headerY = 0.55;
    const linkStartY = 0.25;
    const linkStep = 1.8 * (typo.link?.fontSize ?? 13) / 100;

    let colIndex = -1;
    let linkCursor = 0;

    for (const item of items) {
      const role = item.role;
      const text = item.text;
      if (role === 'wordmark') {
        makeText(
          text,
          { fontSize: typo.wordmark?.fontSize ?? 34, color: PAPER, letterSpacingEm: typo.wordmark?.letterSpacing ?? 0.02 },
          leftPad,
          headerY
        );
        makeAccentBar(leftPad + 0.15, headerY - 0.4);
      } else if (role === 'column-header') {
        colIndex += 1;
        linkCursor = 0;
        const x = colStartX[Math.min(colIndex, colStartX.length - 1)];
        makeText(
          text,
          { fontSize: typo['column-header']?.fontSize ?? 9, color: PAPER, letterSpacingEm: typo['column-header']?.letterSpacing ?? 0.12 },
          x,
          headerY
        );
      } else if (role === 'link') {
        const x = colStartX[Math.min(Math.max(colIndex, 0), colStartX.length - 1)];
        const y = linkStartY - linkCursor * linkStep;
        makeText(
          text,
          { fontSize: typo.link?.fontSize ?? 13, color: PAPER, letterSpacingEm: typo.link?.letterSpacing ?? 0 },
          x,
          y
        );
        linkCursor += 1;
      } else if (role === 'legal') {
        makeText(
          text,
          { fontSize: typo.legal?.fontSize ?? 9, color: PAPER, letterSpacingEm: typo.legal?.letterSpacing ?? 0.04 },
          leftPad,
          -0.625
        );
      }
    }
  }

  // ---- assemble ----
  const band = new Group();
  band.name = 'footer-band';
  root.add(band);

  buildBackdrop();
  buildBand();
  makeHairline(1.0 - 0.003, 6.8); // top hairline (spec: full-width, top edge)
  makeHairline(-0.375, 6.8); // second hairline above legal line, 0.25 clearance both sides
  buildText();
  buildLights();

  // ---- motion: single mount fade-up, no stagger ----
  const startY = 0.2;
  root.position.y = startY;
  const motionState = { t: 0 };

  function setOpacity(t) {
    for (const m of disposables.materials) {
      m.transparent = true;
      m.opacity = t;
    }
    for (const obj of textMeshes) {
      obj.traverse((child) => {
        if (child.material) {
          child.material.transparent = true;
          if ('opacity' in child.material) child.material.opacity = t;
        }
      });
    }
  }
  setOpacity(0);

  const tl = gsap.timeline();
  tl.to(motionState, {
    t: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => {
      setOpacity(motionState.t);
      root.position.y = startY * (1 - motionState.t);
    },
  });

  // ---- event handlers (no DOM listeners; adapter wires these) ----
  root.userData.handlers = {
    onHoverLink: (linkIndex) => {
      // hover color/translate handled by adapter-driven pointer events if routed here
    },
  };

  // ---- cleanup ----
  root.userData.cleanup = () => {
    tl.kill();
    for (const geo of disposables.geometries) geo.dispose?.();
    for (const mat of disposables.materials) mat.dispose?.();
    for (const light of disposables.lights) light.dispose?.();
    for (const obj of textMeshes) {
      obj.traverse((child) => {
        child.geometry?.dispose?.();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose?.());
        } else {
          child.material?.dispose?.();
        }
      });
    }
    root.clear();
  };

  return root;
}

