  {"id":"text.column-header.1","where":"buildText","how":"createText ATELIER header col0"},
  {"id":"text.link.2","where":"buildText","how":"createText Features link col0"},
  {"id":"text.link.3","where":"buildText","how":"createText Collection link col0"},
  {"id":"text.link.4","where":"buildText","how":"createText Pricing link col0"},
  {"id":"text.column-header.5","where":"buildText","how":"createText COMPANY header col1"},
  {"id":"text.link.6","where":"buildText","how":"createText Journal link col1"},
  {"id":"text.link.7","where":"buildText","how":"createText Visit the Atelier link col1"},
  {"id":"text.link.8","where":"buildText","how":"createText Contact link col1"},
